/// The module that exports `name`: its family's entry, else the root.
pub fn module_of(name: &str) -> &'static str {
    FAMILY_EXPORTS
        .binary_search_by(|(export, _)| (*export).cmp(name))
        .map_or(LANGUAGE_MODULES[0], |at| FAMILY_EXPORTS[at].1)
}
